/* DAWAH X — darimi, অধ্যায় 16 · খণ্ড 16 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][16]=[[3001,3001,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏اسْتَهَلَّ ‏ ‏الْمَوْلُودُ صُلِّيَ عَلَيْهِ وَوُرِثَ ‏","","",""],[3002,3002,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏أَرَى الْعُطَاسَ ‏ ‏اسْتِهْلَالًا ‏","","",""],[3003,3003,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَا يُوَرَّثُ الْمَوْلُودُ حَتَّى ‏ ‏يَسْتَهِلَّ ‏ ‏وَلَا يُصَلَّى عَلَيْهِ حَتَّى ‏ ‏يَسْتَهِلَّ ‏ ‏فَإِذَا ‏ ‏اسْتَهَلَّ ‏ ‏صُلِّيَ عَلَيْهِ وَوُرِّثَ وَكُمِّلَتْ الدِّيَةُ ‏","","",""],[3004,3004,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏وَسَأَلْنَاهُ عَنْ ‏ ‏السِّقْطِ ‏ ‏فَقَالَ ‏ ‏لَا يُصَلَّى عَلَيْهِ وَلَا يُصَلَّى عَلَى مَوْلُودٍ حَتَّى ‏ ‏يَسْتَهِلَّ ‏ ‏صَارِخًا ‏","","",""],[3005,3005,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏إِذَا ابْتَاعَ ‏ ‏الْمُكَاتَبَانِ ‏ ‏أَحَدُهُمَا الْآخَرَ هَذَا هَذَا مِنْ سَيِّدِهِ وَهَذَا هَذَا مِنْ سَيِّدِهِ فَالْبَيْعُ لِلْأَوَّلِ وَيَقُولُ أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏الْوَلَاءُ ‏ ‏لِسَيِّدِ الْبَائِعِ وَيَقُولُونَ إِنَّمَا ابْتَاعَ هَذَا مَا عَلَى ‏ ‏الْمُكَاتَبِ ‏ ‏فَالْوَلَاءُ ‏ ‏لِلسَّيِّدِ ‏","","",""],[3006,3006,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏أَيُّمَا حُرٍّ تَزَوَّجَ أَمَةً فَقَدْ أَرَقَّ نِصْفَهُ وَأَيُّمَا عَبْدٍ تَزَوَّجَ حُرَّةً فَقَدْ أَعْتَقَ نِصْفَهُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي الْوَلَدَ ‏","","",""],[3007,3007,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي الْعَبْدِ يَتَزَوَّجُ الْمَرْأَةَ ثُمَّ يُطَلِّقُهَا وَلَهُ مِنْهَا وَلَدٌ قَالَ ‏ ‏إِنْ كَانَتْ حُرَّةً فَالنَّفَقَةُ عَلَى أُمِّهِ وَإِنْ كَانَ عَبْدًا ‏ ‏يَعْنِي الصَّبِيَّ فَعَلَى ‏ ‏مُوَالِيهِ ‏","","",""],[3008,3008,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏وَلَاؤُهُ ‏ ‏لِمَنْ بَدَأَ بِالْعِتْقِ أَوَّلَ مَرَّةٍ ‏","","",""],[3009,3009,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ تَغْلِبَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏إِنْ ضَمِنَ كَانَ ‏ ‏الْوَلَاءُ ‏ ‏لَهُ وَإِنْ ‏ ‏اسْتَسْعَى ‏ ‏الْعَبْدُ كَانَ ‏ ‏الْوَلَاءُ ‏ ‏بَيْنَهُمْ ‏","","",""],[3010,3010,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏فِي عَبْدٍ بَيْنَ رَجُلَيْنِ أَعْتَقَ أَحَدُهُمَا نَصِيبَهُ قَالَ ‏ ‏يُتَمَّمُ عِتْقُهُ فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ ‏ ‏اسْتُسْعِيَ ‏ ‏الْعَبْدُ فِي النِّصْفِ بِقِيمَةِ عَدْلٍ ‏ ‏وَالْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[3011,3011,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ الْمَعْمَرِيِّ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فِي عَبْدٍ بَيْنَ رَجُلَيْنِ أَعْتَقَ أَحَدَهُمَا نَصِيبَهُ وَأَمْسَكَهُ الْآخَرُ قَالَ ‏ ‏مِيرَاثُهُ بَيْنَهُمَا ‏","","",""],[3012,3012,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏مِيرَاثُهُ لِلَّذِي أَمْسَكَهُ ‏ ‏و قَالَ ‏ ‏قَتَادَةُ ‏ ‏هُوَ لِلْمُعْتِقِ كُلُّهُ وَثَمَنُهُ عَلَيْهِ وَيَقُولُهُ أَهْلُ ‏ ‏الْكُوفَةِ ‏","","",""],[3013,3013,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الرَّجُلِ يَمُوتُ وَيَتْرُكُ ‏ ‏مُكَاتَبًا ‏ ‏وَلَهُ بَنُونَ وَبَنَاتٌ أَيَكُونُ لِلنِّسَاءِ مِنْ ‏ ‏الْوَلَاءِ ‏ ‏شَيْءٌ قَالَ ‏ ‏تَرِثُ النِّسَاءُ مِمَّا عَلَى ظَهْرِهِ مِنْ ‏ ‏مُكَاتَبَتِهِ ‏ ‏وَيَكُونُ ‏ ‏الْوَلَاءُ ‏ ‏لِلرِّجَالِ دُونَ النِّسَاءِ إِلَّا مَا كَاتَبْنَ أَوْ أَعْتَقْنَ ‏","","",""],[3014,3014,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏لَا تَرِثُ النِّسَاءُ مِنْ ‏ ‏الْوَلَاءِ ‏ ‏إِلَّا مَا أَعْتَقْنَ أَوْ أَعْتَقَ مَنْ أَعْتَقْنَ ‏","","",""],[3015,3015,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ ‏ ‏تُوُفِّيَ رَجُلٌ وَتَرَكَ ‏ ‏مُكَاتَبًا ‏ ‏ثُمَّ مَاتَ ‏ ‏الْمُكَاتَبُ ‏ ‏وَتَرَكَ مَالًا فَجَعَلَ ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏مَا بَقِيَ مِنْ ‏ ‏مُكَاتَبَتِهِ ‏ ‏بَيْنَ بَنِي ‏ ‏مَوْلَاهُ ‏ ‏الرِّجَالُ وَالنِّسَاءُ عَلَى مِيرَاثِهِمْ وَمَا فَضَلَ مِنْ الْمَالِ بَعْدَ ‏ ‏كِتَابَتِهِ ‏ ‏فَلِلرِّجَالِ مِنْهُمْ مِنْ بَنِي ‏ ‏مَوْلَاهُ ‏ ‏دُونَ النِّسَاءِ ‏","","",""],[3016,3016,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏وَعَلِيٍّ ‏ ‏وَزَيْدٍ ‏ ‏أَنَّهُمْ قَالُوا ‏ ‏الْوَلَاءُ ‏ ‏لِلْكُبْرِ ‏ ‏وَلَا يَرِثُونَ النِّسَاءَ مِنْ ‏ ‏الْوَلَاءِ ‏ ‏إِلَّا مَا أَعْتَقْنَ أَوْ ‏ ‏كَاتَبْنَ ‏","","",""],[3017,3017,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّهُمْ قَالُوا ‏ ‏لَا تَرِثُ النِّسَاءُ مِنْ ‏ ‏الْوَلَاءِ ‏ ‏إِلَّا مَا أَعْتَقْنَ أَوْ ‏ ‏كَاتَبْنَ ‏","","",""],[3018,3018,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَا تَرِثُ النِّسَاءُ مِنْ ‏ ‏الْوَلَاءِ ‏ ‏إِلَّا مَا أَعْتَقْنَ أَوْ أَعْتَقَ مَنْ أَعْتَقْنَ إِلَّا ‏ ‏الْمُلَاعَنَةُ ‏ ‏فَإِنَّهَا تَرِثُ مَنْ أَعْتَقَ ابْنُهَا وَالَّذِي انْتَفَى مِنْهُ أَبُوهُ ‏","","",""],[3019,3019,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ كَانَ يَرِثُ ‏ ‏مَوَالِيَ ‏ ‏عُمَرَ ‏ ‏دُونَ بَنَاتِ ‏ ‏عُمَرَ ‏","","",""],[3020,3020,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏فِي امْرَأَةٍ مَاتَتْ وَتَرَكَتْ بَنِيهَا فَوَرِثُوهَا مَالًا ‏ ‏وَمَوَالِيَ ‏ ‏ثُمَّ مَاتَ بَنُوهَا قَالَ ‏ ‏يَرْجِعُ ‏ ‏الْوَلَاءُ ‏ ‏إِلَى ‏ ‏عَصَبَةِ ‏ ‏الْمَرْأَةِ ‏","","",""],[3021,3021,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ رَجُلٍ ‏ ‏كَاتَبَ ‏ ‏عَبْدًا لَهُ ثُمَّ مَاتَ وَتَرَكَ وَلَدًا رِجَالًا وَنِسَاءً قَالَ ‏ ‏لِلذُّكُورِ دُونَ الْإِنَاثِ ‏","","",""],[3022,3022,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏فِي امْرَأَةٍ مَاتَتْ وَتَرَكَتْ ‏ ‏مَوْلًى ‏ ‏قَالَ ‏ ‏الْوَلَاءُ ‏ ‏لِبَنِيهَا فَإِذَا مَاتُوا رَجَعَ إِلَى ‏ ‏عَصَبَتِهَا ‏","","",""],[3023,3023,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏لَيْسَ لِلنِّسَاءِ مِنْ ‏ ‏الْوَلَاءِ ‏ ‏شَيْءٌ إِلَّا مَا أَعْتَقَتْ هِيَ بِنَفْسِهَا ‏","","",""],[3024,3024,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏مَاتَ ‏ ‏مَوْلًى ‏ ‏لِعُمَرَ ‏ ‏فَسَأَلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَقَالَ هَلْ لِبَنَاتِ ‏ ‏عُمَرَ ‏ ‏مِنْ مِيرَاثِهِ شَيْءٌ قَالَ ‏ ‏مَا ‏ ‏أَرَى لَهُنَّ شَيْئًا وَإِنْ شِئْتَ أَنْ تُعْطِيَهُنَّ أَعْطَيْتَهُنَّ ‏","","",""],[3025,3025,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏يُحْرِزُ ‏ ‏الْوَلَاءَ ‏ ‏مَنْ يُحْرِزُ الْمِيرَاثَ ‏","","",""],[3026,3026,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏أَنَّ ‏ ‏امْرَأَةً مِنْ ‏ ‏مُحَارِبٍ ‏ ‏وَهَبَتْ ‏ ‏وَلَاءَ عَبْدِهَا ‏ ‏لِنَفْسِهِ فَأَعْتَقَتْهُ فَوَهَبَ ‏ ‏وَلَاءَ نَفْسِهِ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏وَمَاتَتْ فَخَاصَمَتْ الْمَوَالِي إِلَى ‏ ‏عُثْمَانَ ‏ ‏فَدَعَا ‏ ‏عُثْمَانُ ‏ ‏الْبَيِّنَةَ عَلَى مَا قَالَ قَالَ فَأَتَى الْبَيِّنَةُ فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏اذْهَبْ ‏ ‏فَوَالِ ‏ ‏مَنْ شِئْتَ قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَوَالَى ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَمْرِو بْنِ حَزْمٍ ‏","","",""],[3027,3027,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَلَاءِ ‏ ‏وَعَنْ هِبَتِهِ ‏","","",""],[3028,3028,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ ‏ ‏الْوَلَاءِ ‏ ‏وَعَنْ هِبَتِهِ ‏","","",""],[3029,3029,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏لَا يُبَاعُ ‏ ‏الْوَلَاءُ ‏ ‏وَلَا يُوهَبُ وَالْوَلَاءُ لِمَنْ أَعْتَقَ ‏","","",""],[3030,3030,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏الْوَلَاءُ ‏ ‏لُحْمَةٌ كَلُحْمَةِ النَّسَبِ لَا يُبَاعُ وَلَا يُوهَبُ ‏","","",""],[3031,3031,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَسَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُمَا ‏ ‏كَرِهَا بَيْعَ ‏ ‏الْوَلَاءِ ‏","","",""],[3032,3032,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَا يُبَاعُ ‏ ‏الْوَلَاءُ ‏ ‏أَيُؤْكَلُ بِرَقَبَةِ رَجُلٍ مَرَّتَيْنِ ‏","","",""],[3033,3033,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏الْفَرَائِضُ ‏ ‏مِنْ سِتَّةٍ لَا ‏ ‏نُعِيلُهَا ‏","","",""],[3034,3034,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِمْرَانَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ مَيْسَرَةَ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏اخْتُصِمَ إِلَى ‏ ‏شُرَيْحٍ ‏ ‏فِي بِنْتَيْنِ وَأَبَوَيْنِ وَزَوْجٍ فَقَضَى فِيهَا فَأَقْبَلَ الزَّوْجُ ‏ ‏يَشْكُوهُ فِي الْمَسْجِدِ فَأَرْسَلَ إِلَيْهِ ‏ ‏عَبْدَ اللَّهِ بْنَ رَبَاحٍ ‏ ‏فَأَخَذَهُ وَبَعَثَ إِلَى ‏ ‏شُرَيْحٍ ‏ ‏فَقَالَ مَا يَقُولُ هَذَا قَالَ هَذَا ‏ ‏يَخَالُنِي ‏ ‏امْرَأً جَائِرًا وَأَنَا ‏ ‏إِخَالُهُ ‏ ‏امْرَأً فَاجِرًا يُظْهِرُ الشَّكْوَى وَيَكْتُمُ قَضَاءً سَائِرًا فَقَالَ لَهُ الرَّجُلُ مَا تَقُولُ فِي بِنْتَيْنِ وَأَبَوَيْنِ وَزَوْجٍ فَقَالَ ‏ ‏لِلزَّوْجِ الرُّبُعُ مِنْ جَمِيعِ الْمَالِ وَلِلْأَبَوَيْنِ السُّدُسَانِ وَمَا بَقِيَ ‏ ‏فَلِلِابْنَتَيْنِ قَالَ فَلِأَيِّ شَيْءٍ نَقَصْتَنِي قَالَ لَيْسَ أَنَا نَقَصْتُكَ اللَّهُ نَقَصَكَ ‏ ‏لِلِابْنَتَيْنِ الثُّلُثَانِ وَلِلْأَبَوَيْنِ السُّدُسَانِ وَلِلزَّوْجِ الرُّبُعُ فَهِيَ مِنْ سَبْعَةٍ وَنِصْفٍ ‏ ‏فَرِيضَةً ‏ ‏فَرِيضَتُكَ ‏ ‏عَائِلَةٌ ‏","","",""],[3035,3035,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏وَعُمَرَ ‏ ‏وَزَيْدٍ ‏ ‏قَالُوا ‏ ‏الْوَالِدُ يَجُرُّ ‏ ‏وَلَاءَ وَلَدِهِ ‏","","",""],[3036,3036,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏الْجَدُّ يَجُرُّ ‏ ‏الْوَلَاءَ ‏","","",""],[3037,3037,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏قَالَ ‏ ‏الْوَالِدُ يَجُرُّ ‏ ‏وَلَاءَ وَلَدِهِ ‏","","",""],[3038,3038,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏فِي مَمْلُوكٍ تُوُفِّيَ وَلَهُ أَبٌ حُرٌّ وَلَهُ بَنُونَ مِنْ امْرَأَةٍ حُرَّةٍ لِمَنْ ‏ ‏وَلَاءُ ‏ ‏وَلَدِهِ قَالَ ‏ ‏لِمَوَالِي ‏ ‏الْجَدِّ ‏","","",""],[3039,3039,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي ‏ ‏مُكَاتَبٍ ‏ ‏مَاتَ وَقَدْ أَدَّى نِصْفَ ‏ ‏مُكَاتَبَتِهِ ‏ ‏وَلَهُ وَلَدٌ مِنْ امْرَأَةٍ أَحْرَارٌ قَالَ ‏ ‏مَا أُرَاهُ إِلَّا قَدْ جَرَّ ‏ ‏وَلَاءَ ‏ ‏وَلَدِهِ ‏","","",""],[3040,3040,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏شُرَيْحٌ ‏ ‏لَا يَرْجِعُ عَنْ قَضَاءٍ يَقْضِي بِهِ ‏ ‏فَحَدَّثَهُ ‏ ‏الْأَسْوَدُ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏إِذَا تَزَوَّجَ الْمَمْلُوكُ الْحُرَّةَ فَوَلَدَتْ أَوْلَادًا أَحْرَارًا ثُمَّ عُتِقَ بَعْدَ ذَلِكَ رَجَعَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَوَالِي ‏ ‏أَبِيهِمْ فَأَخَذَ بِهِ ‏ ‏شُرَيْحٌ ‏","","",""],[3041,3041,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏فِي الْمَمْلُوكِ يَكُونُ تَحْتَهُ الْحُرَّةُ ‏ ‏يُعْتَقُ الْوَلَدُ بِعِتْقِ أُمِّهِ فَإِذَا عُتِقَ الْأَبُ جَرَّ ‏ ‏الْوَلَاءَ ‏","","",""],[3042,3042,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ شِنْظِيرٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏فِي الْحُرَّةِ تَحْتَ الْعَبْدِ قَالَ ‏ ‏أَمَّا مَا وَلَدَتْ مِنْهُ وَهُوَ عَبْدٌ ‏ ‏فَوَلَاؤُهُمْ ‏ ‏لِأَهْلِ نِعْمَتِهَا ‏ ‏وَمَا وَلَدَتْ مِنْهُ وَهُوَ حُرٌّ ‏ ‏فَوَلَاؤُهُمْ ‏ ‏لِأَهْلِ نِعْمَتِهِ ‏","","",""],[3043,3043,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏إِذَا كَانَتْ الْحُرَّةُ تَحْتَ الْمَمْلُوكِ فَوَلَدَتْ لَهُ غُلَامًا فَإِنَّهُ يُعْتَقُ بِعِتْقِ أُمِّهِ ‏ ‏وَوَلَاؤُهُ ‏ ‏لِمَوَالِي أُمِّهِ فَإِذَا أُعْتِقَ الْأَبُ جَرَّ الْوَلَاءَ إِلَى مَوَالِي أَبِيهِ ‏","","",""],[3044,3044,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ أُمِّي ‏ ‏مَوْلَاةً ‏ ‏لِلْحُرَقَةِ ‏ ‏وَكَانَ أَبِي ‏ ‏يَعْقُوبُ ‏ ‏مُكَاتَبًا ‏ ‏لِمَالِكِ بْنِ أَوْسِ بْنِ الْحَدَثَانِ النَّصْرِيِّ ‏ ‏ثُمَّ إِنَّ أَبِي أَدَّى ‏ ‏كِتَابَتَهُ ‏ ‏فَدَخَلَ ‏ ‏الْحُرَقِيُّ ‏ ‏عَلَى ‏ ‏عُثْمَانَ ‏ ‏يَسْأَلُ الْحَقَّ ‏ ‏يَعْنِي الْعَطَاءَ ‏ ‏وَعِنْدَهُ ‏ ‏مَالِكُ بْنُ أَوْسٍ ‏ ‏فَقَالَ ذَاكَ ‏ ‏مَوْلَايَ ‏ ‏فَاخْتَصَمَا إِلَى ‏ ‏عُثْمَانَ ‏ ‏فَقَضَى بِهِ ‏ ‏لِلْحُرَقِيِّ ‏","","",""],[3045,3045,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏سَهْمُ بْنُ يَزِيدَ الْحَمْرَاوِيُّ ‏ ‏أَنَّ رَجُلًا تُوُفِّيَ وَلَيْسَ لَهُ وَارِثٌ ‏ ‏فَكُتِبَ فِيهِ إِلَى ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏وَهُوَ خَلِيفَةٌ ‏ ‏فَكَتَبَ ‏ ‏أَنْ اقْتَسِمُوا مِيرَاثَهُ عَلَى مَنْ كَانَ يَأْخُذُ مَعَهُمْ الْعَطَاءَ فَقُسِمَ مِيرَاثُهُ عَلَى مَنْ كَانَ يَأْخُذُ مَعَهُمْ الْعَطَاءَ فِي ‏ ‏عِرَافَتِهِ ‏","","",""],[3046,3046,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ مُسْلِمٍ يَبِيتُ لَيْلَتَيْنِ وَلَهُ شَيْءٌ يُوصِي فِيهِ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ ‏","","",""],[3047,3047,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ لَا يَأْكُلُ فِي كُلِّ بَطْنِهِ وَلَا تَزَالُ وَصِيَّتُهُ تَحْتَ جَنْبِهِ ‏","","",""],[3048,3048,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ عُمَرَ ‏ ‏قَالَ قَالَ لِي ‏ ‏ثُمَامَةُ بْنُ حَزْنٍ ‏ ‏مَا فَعَلَ أَبُوكَ قُلْتُ مَاتَ قَالَ فَهَلْ أَوْصَى فَإِنَّهُ كَانَ يُقَالُ ‏ ‏إِذَا أَوْصَى الرَّجُلُ كَانَ وَصِيَّتُهُ تَمَامًا لِمَا ضَيَّعَ مِنْ زَكَاتِهِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏و قَالَ ‏ ‏غَيْرُهُ ‏ ‏الْقَاسِمُ بْنُ عَمْرٍو ‏","","",""],[3049,3049,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏كَانَ يُقَالُ ‏ ‏مَنْ أَوْصَى بِوَصِيَّةٍ فَلَمْ يَجُرْ وَلَمْ يَحِفْ كَانَ لَهُ مِنْ الْأَجْرِ مِثْلُ مَا أَنْ لَوْ تَصَدَّقَ بِهِ فِي حَيَاتِهِ ‏","","",""],[3050,3050,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِهَرِمِ بْنِ حَيَّانَ ‏ ‏أَوْصِهْ قَالَ ‏ ‏أُوصِيكُمْ بِالْآيَاتِ الْأَوَاخِرِ مِنْ سُورَةِ ‏ ‏النَّحْلِ ‏ ‏وَقَرَأَ ‏ ‏ابْنُ حَيَّانَ ‏ { ‏ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَالَّذِينَ هُمْ مُحْسِنُونَ ‏}","","",""],[3051,3051,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ مُصَرِّفٍ الْيَامِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي أَوْفَى ‏ ‏أَوْصَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا قُلْتُ فَكَيْفَ كُتِبَ عَلَى النَّاسِ الْوَصِيَّةُ ‏ ‏أَوْ أُمِرُوا بِالْوَصِيَّةِ ‏ ‏فَقَالَ ‏ ‏أَوْصَى بِكِتَابِ اللَّهِ ‏ ‏و قَالَ ‏ ‏هُزَيْلُ بْنُ شُرَحْبِيلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏كَانَ يَتَأَمَّرُ عَلَى وَصِيِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَدَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَنَّهُ وَجَدَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَهْدًا ‏ ‏فَخَزَمَ ‏ ‏أَنْفَهُ ‏ ‏بِخِزَامَةٍ ‏","","",""],[3052,3052,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ { ‏إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ ‏} ‏قَالَ ‏ ‏الْخَيْرُ الْمَالُ كَانَ يُقَالُ أَلْفًا فَمَا فَوْقَ ذَلِكَ ‏","","",""],[3053,3053,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏أَنَّهُ أَوْصَى ‏ ‏ذِكْرُ مَا أَوْصَى بِهِ ‏ ‏أَوْ هَذَا ذِكْرُ مَا أَوْصَى بِهِ ‏ ‏مُحَمَّدُ بْنُ أَبِي عَمْرَةَ ‏ ‏بَنِيهِ وَأَهْلَ بَيْتِهِ أَنْ ‏ { ‏اتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ وَأَطِيعُوا اللَّهَ وَرَسُولَهُ إِنْ كُنْتُمْ مُؤْمِنِينَ ‏} ‏وَأَوْصَاهُمْ بِمَا أَوْصَى بِهِ ‏ ‏إِبْرَاهِيمُ ‏ ‏بَنِيهِ ‏ ‏وَيَعْقُوبُ ‏ { ‏يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَى لَكُمْ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ‏} ‏وَأَوْصَاهُمْ أَنْ لَا يَرْغَبُوا أَنْ يَكُونُوا ‏ ‏مَوَالِيَ ‏ ‏الْأَنْصَارِ ‏ ‏وَإِخْوَانَهُمْ فِي الدِّينِ وَأَنَّ الْعِفَّةَ وَالصِّدْقَ خَيْرٌ وَأَتْقَى مِنْ الزِّنَا وَالْكَذِبِ إِنْ حَدَثَ بِهِ حَدَثٌ فِي مَرَضِي هَذَا قَبْلَ أَنْ أُغَيِّرَ وَصِيَّتِي هَذِهِ ثُمَّ ذَكَرَ حَاجَتَهُ ‏","","",""],[3054,3054,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏هَكَذَا كَانُوا يُوصُونَ هَذَا مَا أَوْصَى بِهِ فُلَانُ بْنُ فُلَانٍ أَنَّهُ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏ { ‏وَأَنَّ السَّاعَةَ آتِيَةٌ لَا رَيْبَ فِيهَا وَأَنَّ اللَّهَ يَبْعَثُ مَنْ فِي الْقُبُورِ ‏} ‏وَأَوْصَى مَنْ تَرَكَ بَعْدَهُ مِنْ أَهْلِهِ أَنْ يَتَّقُوا اللَّهَ وَيُصْلِحُوا ذَاتَ بَيْنِهِمْ وَأَنْ يُطِيعُوا اللَّهَ وَرَسُولَهُ إِنْ كَانُوا مُؤْمِنِينَ وَأَوْصَاهُمْ بِمَا أَوْصَى بِهِ ‏ ‏إِبْرَاهِيمُ ‏ ‏بَنِيهِ ‏ ‏وَيَعْقُوبُ ‏ { ‏يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَى لَكُمْ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ‏} ‏وَأَوْصَى إِنْ حَدَثَ بِهِ حَدَثٌ مِنْ وَجَعِهِ هَذَا أَنَّ حَاجَتَهُ كَذَا وَكَذَا ‏","","",""],[3055,3055,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏الْوَلِيدُ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ غَيْلَانَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏حِينَ أَوْصَى قَالَ تَشَهُّدُ ‏ ‏هَذَا مَا شَهِدَ بِهِ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ وَيُؤْمِنُ بِاللَّهِ وَيَكْفُرُ بِالطَّاغُوتِ عَلَى ذَلِكَ ‏ ‏يَحْيَا إِنْ شَاءَ اللَّهُ وَيَمُوتُ وَيُبْعَثُ وَأَوْصَى فِيمَا رَزَقَهُ اللَّهُ فِيمَا تَرَكَ إِنْ حَدَثَ بِهِ حَدَثٌ وَهُوَ كَذَا وَكَذَا إِنْ لَمْ يُغَيِّرْ شَيْئًا مِمَّا فِي هَذِهِ الْوَصِيَّةِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏قَالَ ‏ ‏هَذِهِ وَصِيَّةُ ‏ ‏أَبِي الدَّرْدَاءِ ‏","","",""],[3056,3056,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏الرَّبِيعُ بْنُ خُثَيْمٍ ‏ ‏وَصِيَّتَهُ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏هَذَا مَا أَوْصَى بِهِ ‏ ‏الرَّبِيعُ بْنُ خُثَيْمٍ ‏ ‏وَأَشْهَدَ اللَّهَ عَلَيْهِ وَكَفَى بِاللَّهِ شَهِيدًا وَجَازِيًا لِعِبَادِهِ الصَّالِحِينَ وَمُثِيبًا بِأَنِّي رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏نَبِيًّا وَإِنِّي آمُرُ نَفْسِي وَمَنْ أَطَاعَنِي أَنْ نَعْبُدَ اللَّهَ فِي الْعَابِدِينَ وَنَحْمَدَهُ فِي الْحَامِدِينَ وَأَنْ نَنْصَحَ لِجَمَاعَةِ الْمُسْلِمِينَ ‏","","",""],[3057,3057,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏دَخَلَ عَلَى مَرِيضٍ فَذَكَرُوا لَهُ الْوَصِيَّةَ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏قَالَ اللَّهُ ‏ { ‏إِنْ تَرَكَ خَيْرًا ‏} ‏وَلَا ‏ ‏أُرَاهُ تَرَكَ خَيْرًا ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏فَحَفِظْتُ أَنَّهُ تَرَكَ أَكْثَرَ مِنْ سَبْعِ مِائَةٍ ‏","","",""],[3058,3058,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كُنَاسَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏عَلَى رَجُلٍ مِنْ قَوْمِهِ يَعُودُهُ فَقَالَ أُوصِي قَالَ ‏ ‏لَا لَمْ تَدَعْ مَالًا فَدَعْ مَالَكَ لِوَلَدِكَ ‏","","",""],[3059,3059,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي رَجُلٍ ‏ ‏أَوْصَى وَالْوَرَثَةُ شُهُودٌ مُقِرُّونَ فَقَالَ لَا يَجُوزُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي إِذَا أَنْكَرُوا بَعْدُ ‏","","",""],[3060,3060,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْحَكَمَ ‏ ‏وَحَمَّادًا ‏ ‏عَنْ ‏ ‏الْأَوْلِيَاءِ ‏ ‏يُجِيزُونَ الْوَصِيَّةَ فَإِذَا مَاتَ لَمْ يُجِيزُوا قَالَا لَا يَجُوزُ ‏","","",""],[3061,3061,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏فِي الرَّجُلِ يُوصِي بِأَكْثَرَ مِنْ ثُلُثِهِ قَالَ ‏ ‏إِنْ أَجَازَتْهُ الْوَرَثَةُ أَجَزْنَاهُ وَإِنْ قَالَتْ الْوَرَثَةُ أَجَزْنَاهُ فَهُمْ بِالْخِيَارِ إِذَا نَفَضُوا أَيْدِيَهُمْ مِنْ الْقَبْرِ ‏","","",""],[3062,3062,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَوْنٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏أَنَّ ‏ ‏رَجُلًا اسْتَأْذَنَ وَرَثَتَهُ أَنْ يُوصِيَ بِأَكْثَرَ مِنْ الثُّلُثِ فَأَذِنُوا لَهُ ثُمَّ رَجَعُوا فِيهِ بَعْدَ مَا مَاتَ فَسُئِلَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ذَلِكَ فَقَالَ ‏ ‏هَذَا ‏ ‏التَّكَرُّهُ ‏ ‏لَا يَجُوزُ ‏","","",""],[3063,3063,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الرَّجُلِ ‏ ‏يُوصِي بِأَكْثَرَ مِنْ الثُّلُثِ فَرَضِيَ الْوَرَثَةُ قَالَ هُوَ جَائِزٌ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَجَزْنَاهُ ‏ ‏يَعْنِي فِي الْحَيَاةِ ‏","","",""],[3064,3064,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهِ وَهُوَ ‏ ‏بِمَكَّةَ ‏ ‏وَلَيْسَ لَهُ إِلَّا ابْنَةٌ فَقُلْتُ لَهُ إِنَّهُ لَيْسَ لِي إِلَّا ابْنَةٌ وَاحِدَةٌ فَأُوصِي بِمَالِي كُلِّهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا قُلْتُ فَأُوصِي بِالنِّصْفِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا قَالَ فَأُوصِي بِالثُّلُثِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الثُّلُثُ وَالثُّلُثُ كَثِيرٌ ‏","","",""],[3065,3065,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اشْتَكَيْتُ ‏ ‏مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ حَتَّى ‏ ‏أُدْنِفْتُ ‏ ‏فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُنِي فَقُلْتُ يَا رَسُولَ اللَّهِ مَا ‏ ‏أُرَانِي إِلَّا لِمَا بِي وَأَنَا ذُو مَالٍ كَثِيرٍ وَإِنَّمَا يَرِثُنِي ابْنَةٌ لِي أَفَأَتَصَدَّقُ بِمَالِي كُلِّهِ قَالَ لَا قُلْتُ فَبِنِصْفِهِ قَالَ لَا قُلْتُ فَالثُّلُثِ قَالَ ‏ ‏الثُّلُثُ وَالثُّلُثُ كَثِيرٌ إِنَّكَ إِنْ تَتْرُكْ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَتْرُكَهُمْ فُقَرَاءَ ‏ ‏يَتَكَفَّفُونَ النَّاسَ ‏ ‏بِأَيْدِيهِمْ وَإِنَّكَ لَا تُنْفِقُ نَفَقَةً إِلَّا آجَرَكَ اللَّهُ فِيهَا حَتَّى مَا تَجْعَلُ فِي ‏ ‏فِي ‏ ‏امْرَأَتِكَ ‏","","",""],[3066,3066,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ زِيَادٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏زِيَادَ بْنَ مَطَرٍ ‏ ‏أَوْصَى فَقَالَ ‏ ‏وَصِيَّتِي مَا اتَّفَقَ عَلَيْهِ فُقَهَاءُ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏فَسَأَلْتُ فَاتَّفَقُوا عَلَى الْخُمُسِ ‏","","",""],[3067,3067,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ زِيَادٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا سَأَلَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَقَالَ ‏ ‏إِنَّ وَارِثِي ‏ ‏كَلَالَةٌ ‏ ‏فَأُوصِي بِالنِّصْفِ قَالَ لَا قَالَ فَالثُّلُثِ قَالَ لَا قَالَ فَالرُّبُعِ قَالَ لَا قَالَ فَالْخُمُسِ قَالَ لَا حَتَّى صَارَ إِلَى الْعُشْرِ فَقَالَ أَوْصِ بِالْعُشْرِ ‏","","",""],[3068,3068,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏إِنَّمَا كَانُوا يُوصُونَ بِالْخُمُسِ وَالرُّبُعِ وَكَانَ الثُّلُثُ مُنْتَهَى الْجَامِحِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي بِالْجَامِحِ الْفَرَسَ ‏ ‏الْجَمُوحَ ‏","","",""],[3069,3069,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏قَالَ أَوْصَيْتُ إِلَى ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏فَقَالَ ‏ ‏مَا كُنْتُ لِأَقْبَلَ وَصِيَّةَ رَجُلٍ لَهُ وَلَدٌ يُوصِي بِالثُّلُثِ ‏","","",""],[3070,3070,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏قَالَ ‏ ‏الثُّلُثُ ‏ ‏جَهْدٌ ‏ ‏وَهُوَ جَائِزٌ ‏","","",""],[3071,3071,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏كَانَ السُّدُسُ أَحَبَّ إِلَيْهِمْ مِنْ الثُّلُثِ ‏","","",""],[3072,3072,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْوَصِيُّ أَمِينٌ فِيمَا أُوصِيَ إِلَيْهِ بِهِ ‏","","",""],[3073,3073,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏قَالَ ‏ ‏أَمْرُ الْوَصِيِّ جَائِزٌ فِي كُلِّ شَيْءٍ إِلَّا فِي ‏ ‏الِابْتِيَاعِ ‏ ‏وَإِذَا بَاعَ بَيْعًا لَمْ ‏ ‏يُقِلْ ‏ ‏وَهُوَ رَأْيُ ‏ ‏يَحْيَى بْنِ حَمْزَةَ ‏","","",""],[3074,3074,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ ‏ ‏الْوَصِيُّ أَمِينٌ فِي كُلِّ شَيْءٍ إِلَّا فِي الْعِتْقِ فَإِنَّ عَلَيْهِ أَنْ ‏ ‏يُقِيمَ الْوَلَاءَ ‏","","",""],[3075,3075,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي مَالِ الْيَتِيمِ ‏ ‏يَعْمَلُ بِهِ الْوَصِيُّ إِذَا أَوْصَى إِلَى الرَّجُلِ ‏","","",""],[3076,3076,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏وَصِيُّ الْيَتِيمِ يَأْخُذُ لَهُ ‏ ‏بِالشُّفْعَةِ ‏ ‏وَالْغَائِبُ عَلَى ‏ ‏شُفْعَتِهِ ‏","","",""],[3077,3077,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ أَهْلِ ‏ ‏دِمَشْقَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏وَعِنْدَهُ ‏ ‏سُلَيْمَانُ بْنُ حَبِيبٍ ‏ ‏وَأَبُو قِلَابَةَ ‏ ‏إِذْ دَخَلَ غُلَامٌ فَقَالَ أَرْضُنَا بِمَكَانِ كَذَا وَكَذَا بَاعَكُمْ الْوَصِيُّ وَنَحْنُ أَطْفَالٌ فَالْتَفَتَ إِلَى ‏ ‏سُلَيْمَانَ بْنِ حَبِيبٍ ‏ ‏فَقَالَ مَا تَقُولُ ‏ ‏فَأَضْجَعَ ‏ ‏فِي الْقَوْلِ فَالْتَفَتَ إِلَى ‏ ‏أَبِي قِلَابَةَ ‏ ‏فَقَالَ ‏ ‏مَا تَقُولُ قَالَ رُدَّ عَلَى الْغُلَامِ أَرْضَهُ قَالَ إِذًا يَهْلِكُ مَالُنَا قَالَ أَنْتَ أَهْلَكْتَهُ ‏","","",""],[3078,3078,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي رَجُلٍ أَوْصَى لِرَجُلٍ بِنِصْفِ مَالِهِ وَلِآخَرَ بِثُلُثِ مَالِهِ قَالَ ‏ ‏يَضْرِبَانِ بِذَلِكَ فِي الثُّلُثِ هَذَا بِالنِّصْفِ وَهَذَا بِالثُّلُثِ ‏","","",""],[3079,3079,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏يُغَيِّرُ صَاحِبُ الْوَصِيَّةِ مِنْهَا مَا شَاءَ غَيْرَ الْعَتَاقَةِ ‏","","",""],[3080,3080,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏يُحْدِثُ الرَّجُلُ فِي وَصِيَّتِهِ مَا شَاءَ ‏ ‏وَمِلَاكُ الْوَصِيَّةِ ‏ ‏آخِرُهَا ‏","","",""],[3081,3081,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ أَبَاهُ أَعْتَقَ رَقِيقًا لَهُ فِي مَرَضِهِ ثُمَّ بَدَا لَهُ أَنْ يَرُدَّهُمْ وَيُعْتِقَ غَيْرَهُمْ قَالَ فَخَاصَمُونِي إِلَى ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ ‏ ‏فَأَجَازَ عِتْقَ الْآخِرِينَ وَأَبْطَلَ عِتْقَ الْأَوَّلِينَ ‏","","",""],[3082,3082,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ ‏ ‏عَنْ ‏ ‏الشَّرِيدِ بْنِ سُوَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ ‏ ‏يُحْدِثُ الرَّجُلُ فِي وَصِيَّتِهِ مَا شَاءَ ‏ ‏وَمِلَاكُ الْوَصِيَّةِ ‏ ‏آخِرُهَا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَمَّامٌ ‏ ‏لَمْ يَسْمَعْ مِنْ ‏ ‏عَمْرٍو ‏ ‏وَبَيْنَهُمَا ‏ ‏قَتَادَةُ ‏","","",""],[3083,3083,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏فِي الرَّجُلِ يُوصِي بِوَصِيَّةٍ ثُمَّ يُوصِي بِأُخْرَى قَالَ ‏ ‏هُمَا جَائِزَتَانِ فِي مَالِهِ ‏","","",""],[3084,3084,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏مِلَاكُ الْوَصِيَّةِ ‏ ‏آخِرُهَا ‏","","",""],[3085,3085,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏إِذَا اتَّهَمَ الْقَاضِي الْوَصِيَّ لَمْ يَعْزِلْهُ وَلَكِنْ يُوَكِّلُ مَعَهُ غَيْرَهُ ‏ ‏وَهُوَ رَأْيُ ‏ ‏الْأَوْزَاعِيِّ ‏","","",""],[3086,3086,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏قَالَ ‏ ‏يَجُوزُ بَيْعُ الْمَرِيضِ وَشِرَاؤُهُ وَنِكَاحُهُ وَلَا يَكُونُ مِنْ الثُّلُثِ ‏","","",""],[3087,3087,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الْحَارِثِ الْعُكْلِيِّ ‏ ‏قَالَ ‏ ‏مَا حَابَى بِهِ الْمَرِيضُ فِي مَرَضِهِ مِنْ بَيْعٍ أَوْ شِرَاءٍ فَهُوَ فِي ثُلُثِهِ ‏ ‏قِيمَةُ عَدْلٍ ‏","","",""],[3088,3088,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى هُوَ ابْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏أَعْطَتْ امْرَأَةٌ مِنْ أَهْلِنَا وَهِيَ حَامِلٌ فَسُئِلَ ‏ ‏الْقَاسِمُ ‏ ‏فَقَالَ ‏ ‏هُوَ مِنْ جَمِيعِ الْمَالِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَنَحْنُ نَقُولُ إِذَا ضَرَبَهَا الْمَخَاضُ فَمَا أَعْطَتْ فَمِنْ الثُّلُثِ ‏","","",""],[3089,3089,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي رَجُلٍ قَالَ لِغُلَامِهِ إِنْ دَخَلْتُ دَارَ فُلَانٍ فَغُلَامِي حُرٌّ ثُمَّ دَخَلَهَا وَهُوَ مَرِيضٌ قَالَ ‏ ‏يُعْتَقُ مِنْ الثُّلُثِ وَإِنْ دَخَلَ فِي صِحَّتِهِ عُتِقَ مِنْ جَمِيعِ الْمَالِ ‏","","",""],[3090,3090,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏حَدَّثَنَا ‏ ‏النُّعْمَانُ بْنُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ الْوَرَثَةُ مَحَاوِيجَ فَلَا ‏ ‏أَرَى بَأْسًا أَنْ يُرَدَّ عَلَيْهِمْ مِنْ الثُّلُثِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِلْأَوْزَاعِيِّ ‏ ‏فَأَعْجَبَهُ ‏","","",""],[3091,3091,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏ح ‏ ‏و أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَا ‏ ‏إِذَا شَهِدَ شَاهِدَانِ مِنْ الْوَرَثَةِ جَازَ عَلَى جَمِيعِهِمْ وَإِذَا شَهِدَ وَاحِدٌ فَفِي نَصِيبِهِ بِحِصَّتِهِ ‏","","",""],[3092,3092,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الشَّعْبِيَّ ‏ ‏يَقُولُ ‏ ‏إِذَا شَهِدَ رَجُلٌ مِنْ الْوَرَثَةِ فَفِي نَصِيبِهِ بِحِصَّتِهِ ثُمَّ قَالَ بَعْدَ ذَلِكَ فِي جَمِيعِ حِصَّتِهِ ‏","","",""],[3093,3093,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ عَبْدُ رَبِّهِ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى الرَّجُلُ بِالثُّلُثِ وَالرُّبُعِ فَفِي ‏ ‏الْعَيْنِ ‏ ‏وَالدَّيْنِ وَإِذَا أَوْصَى بِخَمْسِينَ أَوْ سِتِّينَ إِلَى الْمِائَةِ فَفِي ‏ ‏الْعَيْنِ ‏ ‏حَتَّى يَبْلُغَ الثُّلُثَ ‏","","",""],[3094,3094,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ أَحَقُّ بِثُلُثِ مَالِهِ يَضَعُهُ فِي أَيِّ مَالِهِ شَاءَ ‏","","",""],[3095,3095,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي حَبِيبَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏عَنْ رَجُلٍ جَعَلَ دَرَاهِمَ فِي سَبِيلِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الَّذِي يَتَصَدَّقُ عِنْدَ مَوْتِهِ أَوْ يُعْتِقُ كَالَّذِي يُهْدِي بَعْدَ مَا شَبِعَ ‏","","",""],[3096,3096,"","","‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الرَّجُلِ يُوصِي بِأَشْيَاءَ وَفِيهَا الْعِتْقُ فَيُجَاوِزُ الثُّلُثَ ‏ ‏قَالَ ‏ ‏يُبْدَأُ بِالْعِتْقِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏بِالْحِصَصِ ‏","","",""],[3097,3097,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَافَى ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏مَنْ أَوْصَى أَوْ أَعْتَقَ فَكَانَ فِي وَصِيَّتِهِ ‏ ‏عَوْلٌ ‏ ‏دَخَلَ ‏ ‏الْعَوْلُ ‏ ‏عَلَى أَهْلِ الْعَتَاقَةِ وَأَهْلِ الْوَصِيَّةِ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏عَطَاءٌ ‏ ‏إِنَّ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏غَلَبُونَا يَبْدَءُونَ بِالْعَتَاقَةِ قَبْلُ ‏","","",""],[3098,3098,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏فِي الَّذِي يُوصِي بِعِتْقٍ وَغَيْرِهِ فَيَزِيدُ عَلَى الثُّلُثِ قَالَ بِالْحِصَصِ ‏","","",""],[3099,3099,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ شِنْظِيرٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي رَجُلٍ أَوْصَى بِأَكْثَرَ مِنْ الثُّلُثِ وَفِيهِ عِتْقٌ قَالَ ‏ ‏يُبْدَأُ بِالْعِتْقِ ‏","","",""],[3100,3100,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏يُبْدَأُ بِالْعَتَاقَةِ قَبْلَ الْوَصِيَّةِ ‏","","",""],[3101,3101,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الرَّجُلِ يُوصِي لِبَنِي فُلَانٍ قَالَ ‏ ‏غَنِيُّهُمْ وَفَقِيرُهُمْ وَذَكَرُهُمْ وَأُنْثَاهُمْ سَوَاءٌ ‏","","",""],[3102,3102,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى لِبَنِي فُلَانٍ فَالذَّكَرُ وَالْأُنْثَى فِيهِ سَوَاءٌ ‏","","",""],[3103,3103,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ بْنُ مُوسَى الْهَمْدَانِيُّ ‏ ‏حَدَّثَنِي ‏ ‏سَيَّارُ بْنُ أَبِي كَرِبٍ ‏ ‏أَنَّ آتِيًا أَتَى ‏ ‏شُرَيْحًا ‏ ‏فَسَأَلَهُ عَنْ رَجُلٍ أَوْصَى بِسَهْمٍ مِنْ مَالِهِ قَالَ ‏ ‏تُحْسَبُ ‏ ‏الْفَرِيضَةُ ‏ ‏فَمَا بَلَغَ سِهَامَهَا أُعْطِيَ الْمُوصَى لَهُ سَهْمًا كَأَحَدِهَا ‏","","",""],[3104,3104,"","","‏ ‏أَخْبَرَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏قَالَ ‏ ‏إِذَا تَصَدَّقَ الرَّجُلُ عَلَى بَعْضِ وَرَثَتِهِ وَهُوَ صَحِيحٌ بِأَكْثَرَ مِنْ النِّصْفِ رُدَّ إِلَى الثُّلُثِ وَإِذَا أَعْطَى النِّصْفَ جَازَ لَهُ ذَلِكَ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وَكَانَ قُضَاةُ أَهْلِ ‏ ‏دِمَشْقَ ‏ ‏يَقْضُونَ بِذَلِكَ ‏","","",""],[3105,3105,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْكَفَنُ مِنْ جَمِيعِ الْمَالِ ‏","","",""],[3106,3106,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي رَجُلٍ مَاتَ وَتَرَكَ قِيمَةَ أَلْفَيْ دِرْهَمٍ وَعَلَيْهِ مِثْلُهَا أَوْ أَكْثَرُ قَالَ ‏ ‏يُكَفَّنُ مِنْهَا وَلَا يُعْطَى دَيْنُهُ ‏","","",""],[3107,3107,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏يُبْدَأُ بِالْكَفَنِ ثُمَّ الدَّيْنِ ثُمَّ الْوَصِيَّةِ ‏","","",""],[3108,3108,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي الْمَرْأَةِ تَمُوتُ قَالَ ‏ ‏تُكَفَّنُ مِنْ مَالِهَا لَيْسَ عَلَى الزَّوْجِ شَيْءٌ ‏","","",""],[3109,3109,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ ‏ ‏الْحَنُوطُ ‏ ‏وَالْكَفَنُ مِنْ رَأْسِ الْمَالِ ‏","","",""],[3110,3110,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏الْكَفَنُ مِنْ وَسَطِ الْمَالِ يُكَفَّنُ عَلَى قَدْرِ مَا كَانَ يَلْبَسُ فِي حَيَاتِهِ ثُمَّ يُخْرَجُ الدَّيْنُ ثُمَّ الثُّلُثُ ‏","","",""],[3111,3111,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏إِذَا أَوْصَى الرَّجُلُ إِلَى الرَّجُلِ وَهُوَ غَائِبٌ فَلْيَقْبَلْ وَصِيَّتَهُ وَإِنْ كَانَ حَاضِرًا فَهُوَ بِالْخِيَارِ إِنْ شَاءَ قَبِلَ وَإِنْ شَاءَ تَرَكَ ‏","","",""],[3112,3112,"","","‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْحَسَنَ ‏ ‏وَمُحَمَّدًا ‏ ‏عَنْ الرَّجُلِ يُوصِي إِلَى الرَّجُلِ قَالَا ‏ ‏نَخْتَارُ أَنْ يَقْبَلَ ‏","","",""],[3113,3113,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَسْعَدَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى الرَّجُلُ إِلَى الرَّجُلِ وَهُوَ غَائِبٌ فَإِذَا قَدِمَ فَإِنْ شَاءَ قَبِلَ فَإِذَا قَبِلَ لَمْ يَكُنْ لَهُ أَنْ يَرُدَّ ‏","","",""],[3114,3114,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَضَّاحُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى الرَّجُلُ إِلَى الرَّجُلِ فَعُرِضَتْ عَلَيْهِ الْوَصِيَّةُ وَكَانَ غَائِبًا فَقَبِلَ لَمْ يَكُنْ لَهُ أَنْ يَرْجِعَ ‏","","",""],[3115,3115,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى الرَّجُلُ لِإِنْسَانٍ وَهُوَ غَائِبٌ وَكَانَ مَيِّتًا وَهُوَ لَا يَدْرِي فَهِيَ رَاجِعَةٌ ‏","","",""],[3116,3116,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى لِعَبْدِهِ ثُلُثَ مَالِهِ رُبُعَ مَالِهِ خُمُسَ مَالِهِ فَهُوَ مِنْ مَالِهِ دَخَلَتْهُ عَتَاقَةٌ ‏","","",""],[3117,3117,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏قَالَ ‏ ‏كَانَ يُقَالُ ‏ ‏إِنَّ الرَّجُلَ لَيُحْرَمُ بَرَكَةَ مَالِهِ فِي حَيَاتِهِ فَإِذَا كَانَ عِنْدَ الْمَوْتِ تَزَوَّدَ ‏ ‏بِفَجْرَةٍ ‏","","",""],[3118,3118,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏الْمُرَّانِ الْإِمْسَاكُ فِي الْحَيَاةِ وَالتَّبْذِيرُ عِنْدَ الْمَوْتِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يُقَالُ مُرٌّ فِي الْحَيَاةِ وَمُرٌّ عِنْدَ الْمَوْتِ ‏","","",""],[3119,3119,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى الرَّجُلُ لِآخَرَ بِمِثْلِ نَصِيبِ ابْنِهِ فَلَا يَتِمُّ لَهُ مِثْلُ نَصِيبِهِ حَتَّى يَنْقُصَ مِنْهُ ‏","","",""],[3120,3120,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي رَجُلٍ كَانَ لَهُ ثَلَاثَةُ بَنِينَ فَأَوْصَى لِرَجُلٍ مِثْلَ نَصِيبِ أَحَدِهِمْ لَوْ كَانُوا أَرْبَعَةً ‏ ‏قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏يُعْطَى الْخُمُسَ ‏","","",""],[3121,3121,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏قَالَ ‏ ‏سَأَلْنَا ‏ ‏عَامِرًا ‏ ‏عَنْ رَجُلٍ تَرَكَ ابْنَيْنِ وَأَوْصَى بِمِثْلِ نَصِيبِ أَحَدِهِمْ لَوْ كَانُوا ثَلَاثَةً قَالَ ‏ ‏أَوْصَى بِالرُّبُعِ ‏","","",""],[3122,3122,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ فِي رَجُلٍ أَوْصَى بِمِثْلِ نَصِيبِ بَعْضِ الْوَرَثَةِ قَالَ ‏ ‏لَا يَجُوزُ وَإِنْ كَانَ أَقَلَّ مِنْ الثُّلُثِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هُوَ حَسَنٌ ‏","","",""],[3123,3123,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي رَجُلٍ أَوْصَى فِي غَلَّةِ عَبْدِهِ بِدِرْهَمٍ وَغَلَّتُهُ سِتَّةٌ قَالَ ‏ ‏لَهُ سُدُسُهُ ‏","","",""],[3124,3124,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُفْيَانَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَقَرَّ لِوَارِثٍ وَلِغَيْرِ وَارِثٍ بِمِائَةِ دِرْهَمٍ ‏ ‏أَرَى أَنْ أُبْطِلَهُمَا جَمِيعًا ‏","","",""],[3125,3125,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏شُرَيْحٍ ‏ ‏قَالَ ‏ ‏لَا يَجُوزُ إِقْرَارٌ لِوَارِثٍ قَالَ ‏ ‏و قَالَ ‏ ‏الْحَسَنُ ‏ ‏أَحَقُّ مَا جَازَ عَلَيْهِ عِنْدَ مَوْتِهِ أَوَّلَ يَوْمٍ مِنْ أَيَّامِ الْآخِرَةِ وَآخِرَ يَوْمٍ مِنْ أَيَّامِ الدُّنْيَا ‏","","",""],[3126,3126,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏لَا يَجُوزُ لِوَارِثٍ وَصِيَّةٌ ‏","","",""],[3127,3127,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏أَنَّ رَجُلًا يُكْنَى ‏ ‏أَبَا ثَابِتٍ ‏ ‏أَقَرَّ لِامْرَأَتِهِ عِنْدَ مَوْتِهِ أَنَّ لَهَا عَلَيْهِ أَرْبَعَ مِائَةِ دِرْهَمٍ مِنْ صَدَاقِهَا فَأَجَازَهُ ‏ ‏الْحَسَنُ ‏","","",""],[3128,3128,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتَوَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ خَارِجَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ تَحْتَ نَاقَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ ‏ ‏تَقْصَعُ ‏ ‏بِجِرَّتِهَا ‏ ‏وَلُعَابُهَا ‏ ‏يَنُوصُ ‏ ‏بَيْنَ كَتِفَيَّ سَمِعْتُهُ يَقُولُ ‏ ‏أَلَا إِنَّ اللَّهَ قَدْ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ فَلَا يَجُوزُ وَصِيَّةٌ لِوَارِثٍ ‏","","",""],[3129,3129,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ { ‏إِذَا حَضَرَ أَحَدَكُمْ الْمَوْتُ إِنْ تَرَكَ ‏ ‏خَيْرًا ‏ ‏الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ ‏} ‏فَأَمَرَ أَنْ يُوصِيَ لِوَالِدَيْهِ وَأَقَارِبِهِ ثُمَّ نُسِخَ بَعْدَ ذَلِكَ فِي سُورَةِ ‏ ‏النِّسَاءِ ‏ ‏فَجَعَلَ لِلْوَالِدَيْنِ نَصِيبًا مَعْلُومًا وَأَلْحَقَ لِكُلِّ ذِي مِيرَاثٍ نَصِيبَهُ مِنْهُ وَلَيْسَتْ لَهُمْ وَصِيَّةٌ فَصَارَتْ الْوَصِيَّةُ لِمَنْ لَا يَرِثُ مِنْ قَرِيبٍ وَغَيْرِهِ ‏","","",""],[3130,3130,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ الْمَالُ لِلْوَلَدِ وَكَانَتْ الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ فَنَسَخَ اللَّهُ مِنْ ذَلِكَ مَا أَحَبَّ فَجَعَلَ لِلذَّكَرِ مِثْلَ حَظِّ الْأُنْثَيَيْنِ وَجَعَلَ لِلْأَبَوَيْنِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسَ وَالثُّلُثَ وَجَعَلَ لِلْمَرْأَةِ الثُّمُنَ وَالرُّبُعَ وَلِلزَّوْجِ الشَّطْرَ وَالرُّبُعَ ‏","","",""],[3131,3131,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ إِسْمَعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو تُمَيْلَةَ ‏ ‏عَنْ ‏ ‏الْحُسَيْنِ بْنِ وَاقِدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏وَالْحَسَنِ ‏ { ‏إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ ‏} ‏وَكَانَتْ الْوَصِيَّةُ كَذَلِكَ حَتَّى نَسَخَتْهَا آيَةُ الْمِيرَاثِ ‏","","",""],[3132,3132,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏سُئِلَ عَنْ رَجُلٍ أَوْصَى وَلَهُ أَخٌ مُوسِرٌ أَيُوصِ لَهُ قَالَ ‏ ‏نَعَمْ وَإِنْ كَانَ رَبَّ عِشْرِينَ أَلْفًا ثُمَّ قَالَ وَإِنْ كَانَ رَبَّ مِائَةِ أَلْفٍ فَإِنَّ غِنَاهُ لَا يَمْنَعُهُ الْحَقَّ ‏","","",""],[3133,3133,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏وَسَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏فِي رَجُلٍ قَالَ سَيْفِي لِفُلَانٍ فَإِنْ مَاتَ فُلَانٌ فَلِفُلَانٍ فَإِنْ مَاتَ فُلَانٌ فَمَرْجِعُهُ إِلَيَّ قَالَا ‏ ‏هُوَ لِلْأَوَّلِ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏حُمَيْدُ ابْنُ عَبْدِ الرَّحْمَنِ ‏ ‏يُمْضَى كَمَا قَالَ ‏","","",""],[3134,3134,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ ‏ ‏قَالَ ‏ ‏فِي الرَّجُلِ يُعْطِي الرَّجُلَ الْعَطَاءَ فَيَقُولُ هُوَ لَكَ فَإِذَا مُتَّ فَلِفُلَانٍ فَإِذَا مَاتَ فُلَانٌ فَلِفُلَانٍ وَإِذَا مَاتَ فُلَانٌ فَمَرْجِعُهُ إِلَيَّ قَالَ ‏ ‏يُمْضَى كَمَا قَالَ وَإِنْ كَانُوا مِائَةً ‏","","",""],[3135,3135,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَةُ بْنُ هِشَامٍ الرَّاسِبِيُّ ‏ ‏وَكَثِيرُ بْنُ مَعْدَانَ ‏ ‏قَالَا ‏ ‏سَأَلْنَا ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ الرَّجُلِ يُوصِي فِي غَيْرِ قَرَابَتِهِ ‏ ‏فَقَالَ ‏ ‏سَالِمٌ ‏ ‏هِيَ حَيْثُ جَعَلَهَا قَالَ فَقُلْنَا إِنَّ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ يُرَدُّ عَلَى الْأَقْرَبِينَ فَأَنْكَرَ ذَلِكَ وَقَالَ قَوْلًا شَدِيدًا ‏","","",""],[3136,3136,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏إِذَا أَوْصَى الرَّجُلُ فِي قَرَابَتِهِ فَهُوَ لِأَقْرَبِهِمْ بِبَطْنٍ الذَّكَرُ وَالْأُنْثَى فِيهِ سَوَاءٌ ‏","","",""],[3137,3137,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي رَجُلٍ قَالَ أَحَدُ غُلَامَيَّ حُرٌّ ثُمَّ مَاتَ وَلَمْ يُبَيِّنْ قَالَ ‏ ‏الْوَرَثَةُ بِمَنْزِلَتِهِ يُعْتِقُونَ أَيَّهُمَا أَحَبُّوا ‏","","",""],[3138,3138,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ رَجُلًا قَالَ فِي مَرَضِهِ لِفُلَانٍ كَذَا وَلِفُلَانٍ كَذَا وَعَبْدِي فُلَانٌ حُرٌّ وَلَمْ يَقُلْ إِنْ حَدَثَ بِي حَدَثٌ فَبَرَأَ قَالَ ‏ ‏هُوَ مَمْلُوكٌ ‏","","",""],[3139,3139,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏فِي رَجُلٍ أَعْتَقَ غُلَامَهُ عِنْدَ الْمَوْتِ وَلَيْسَ لَهُ غَيْرُهُ وَعَلَيْهِ دَيْنٌ قَالَ ‏ ‏يَسْعَى ‏ ‏لِلْغُرَمَاءِ فِي ثَمَنِهِ ‏","","",""],[3140,3140,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ رَجُلًا اشْتَرَى عَبْدًا بِتِسْعِ مِائَةِ دِرْهَمٍ فَأَعْتَقَهُ وَلَمْ يَقْضِ ثَمَنَ الْعَبْدِ وَلَمْ يَتْرُكْ شَيْئًا فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏يَسْعَى ‏ ‏الْعَبْدُ فِي ثَمَنِهِ ‏","","",""],[3141,3141,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏الْمُدَبَّرُ ‏ ‏مِنْ الثُّلُثِ ‏","","",""],[3142,3142,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْمُدَبَّرُ ‏ ‏مِنْ الثُّلُثِ ‏","","",""],[3143,3143,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏كَثِيرٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏الْمُعْتَقُ عَنْ ‏ ‏دُبُرٍ ‏ ‏مِنْ الثُّلُثِ ‏","","",""],[3144,3144,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏الْمُعْتَقَةُ عَنْ ‏ ‏دُبُرٍ ‏ ‏وَوَلَدُهَا مِنْ الثُّلُثِ ‏","","",""],[3145,3145,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْمُعْتَقُ عَنْ ‏ ‏دُبُرٍ ‏ ‏مِنْ الثُّلُثِ ‏","","",""],[3146,3146,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الشَّقَرِيِّ ‏ ‏وَأَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏الْمُدَبَّرُ ‏ ‏مِنْ جَمِيعِ الْمَالِ ‏","","",""],[3147,3147,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏الْمُعْتَقُ عَنْ ‏ ‏دُبُرٍ ‏ ‏مِنْ جَمِيعِ الْمَالِ ‏ ‏سُئِلَ ‏ ‏أَبُو مُحَمَّد ‏ ‏بِأَيِّهِمَا تَقُولُ قَالَ ‏ ‏مِنْ الثُّلُثِ ‏","","",""],[3148,3148,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مَخْلَدٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَا تَشْهَدْ عَلَى وَصِيَّةٍ حَتَّى تُقْرَأَ عَلَيْكَ وَلَا تَشْهَدْ عَلَى مَنْ لَا تَعْرِفُ ‏","","",""],[3149,3149,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏أَوْصَى لِأُمَّهَاتِ أَوْلَادِهِ بِأَرْبَعَةِ آلَافٍ أَرْبَعَةِ آلَافٍ لِكُلِّ امْرَأَةٍ مِنْهُنَّ ‏","","",""],[3150,3150,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏أَنَّهُ أَجَازَ وَصِيَّةَ ابْنِ ثَلَاثَ عَشْرَةَ سَنَةً ‏","","",""],[3151,3151,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏قَالَ ‏ ‏أَوْصَى غُلَامٌ مِنْ الْحَيِّ ابْنُ سَبْعِ سِنِينَ فَقَالَ ‏ ‏شُرَيْحٌ ‏ ‏إِذَا أَصَابَ الْغُلَامُ فِي وَصِيَّتِهِ جَازَتْ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يُعْجِبُنِي وَالْقُضَاةُ لَا يُجِيزُونَ ‏","","",""],[3152,3152,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏شُرَيْحًا ‏ ‏أَجَازَ وَصِيَّةَ ‏ ‏عَبَّاسِ بْنِ إِسْمَعِيلَ بْنِ مَرْثَدٍ ‏ ‏لِظِئْرِهِ ‏ ‏مِنْ أَهْلِ ‏ ‏الْحِيرَةِ ‏ ‏وَعَبَّاسٌ ‏ ‏صَبِيٌّ ‏","","",""],[3153,3153,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَقَ ‏ ‏قَالَ قَالَ ‏ ‏شُرَيْحٌ ‏ ‏إِذَا اتَّقَى الصَّبِيُّ ‏ ‏الرَّكِيَّةَ ‏ ‏جَازَتْ وَصِيَّتُهُ ‏","","",""],[3154,3154,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏أَنَّ غُلَامًا مِنْهُمْ حِينَ ‏ ‏ثُغِرَ ‏ ‏يُقَالُ لَهُ ‏ ‏مَرْثَدٌ ‏ ‏أَوْصَى ‏ ‏لِظِئْرٍ ‏ ‏لَهُ مِنْ أَهْلِ ‏ ‏الْحِيرَةِ ‏ ‏بِأَرْبَعِينَ دِرْهَمًا فَأَجَازَهُ ‏ ‏شُرَيْحٌ ‏ ‏وَقَالَ ‏ ‏مَنْ أَصَابَ الْحَقَّ أَجَزْنَاهُ ‏","","",""],[3155,3155,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرِ بْنَ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ غُلَامًا ‏ ‏بِالْمَدِينَةِ ‏ ‏حَضَرَهُ الْمَوْتُ وَوَرَثَتُهُ ‏ ‏بِالشَّامِ ‏ ‏وَأَنَّهُمْ ذَكَرُوا ‏ ‏لِعُمَرَ ‏ ‏أَنَّهُ يَمُوتُ فَسَأَلُوهُ أَنْ يُوصِيَ ‏ ‏فَأَمَرَهُ ‏ ‏عُمَرُ ‏ ‏أَنْ يُوصِيَ فَأَوْصَى بِبِئْرٍ يُقَالُ لَهَا ‏ ‏بِئْرُ جُشَمَ ‏ ‏وَإِنَّ أَهْلَهَا بَاعُوهَا بِثَلَاثِينَ أَلْفًا ذَكَرَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَنَّ الْغُلَامَ كَانَ ابْنَ عَشْرِ سِنِينَ ‏ ‏أَوْ ثِنْتَيْ عَشْرَةَ ‏","","",""],[3156,3156,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏يَجُوزُ وَصِيَّةُ الصَّبِيِّ فِي مَالِهِ فِي الثُّلُثِ فَمَا دُونَهُ وَإِنَّمَا يَمْنَعُهُ وَلِيُّهُ ذَلِكَ فِي الصِّحَّةِ رَهْبَةَ ‏ ‏الْفَاقَةِ ‏ ‏عَلَيْهِ فَأَمَّا عِنْدَ الْمَوْتِ فَلَيْسَ لَهُ أَنْ يَمْنَعَهُ ‏","","",""],[3157,3157,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏وَأَيُّوبَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّهُ أُتِيَ فِي جَارِيَةٍ أَوْصَتْ فَجَعَلُوا يُصَغِّرُونَهَا فَقَالَ ‏ ‏مَنْ أَصَابَ الْحَقَّ أَجَزْنَاهُ ‏","","",""],[3158,3158,"","","‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏سُلَيْمًا الْغَسَّانِيَّ ‏ ‏مَاتَ وَهُوَ ابْنُ عَشْرٍ ‏ ‏أَوْ ثِنْتَيْ عَشْرَةَ سَنَةً ‏ ‏فَأَوْصَى بِبِئْرٍ لَهُ قِيمَتُهَا ثَلَاثُونَ أَلْفًا ‏ ‏فَأَجَازَهَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏النَّاسُ يَقُولُونَ ‏ ‏عَمْرُو بْنُ سُلَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏قَبِيصَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنَيْهِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَمُحَمَّدٍ ‏ ‏ابْنَيْ ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِمَا ‏ ‏مِثْلَ ذَلِكَ غَيْرَ أَنَّ أَحَدَهُمَا قَالَ ابْنُ ثَلَاثَ عَشْرَةَ وَقَالَ الْآخَرُ قَبْلَ أَنْ يَحْتَلِمَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏عَنْ ابْنَيْهِ ‏ ‏يَعْنِي ابْنَيْ ‏ ‏أَبِي بَكْرٍ ‏","","",""],[3159,3159,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏وَصِيَّتُهُ لَيْسَتْ بِجَائِزَةٍ إِلَّا مَا لَيْسَ بِذِي بَالٍ ‏ ‏يَعْنِي الْغُلَامَ قَبْلَ أَنْ يَحْتَلِمَ ‏","","",""],[3160,3160,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏لَا يَجُوزُ طَلَاقُ الْغُلَامِ وَلَا وَصِيَّتُهُ وَلَا هِبَتُهُ وَلَا صَدَقَتُهُ وَلَا عَتَاقَتُهُ حَتَّى يَحْتَلِمَ ‏","","",""],[3161,3161,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ غِيَاثٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَا يَجُوزُ طَلَاقُ الصَّبِيِّ وَلَا عِتْقُهُ وَلَا وَصِيَّتُهُ وَلَا شِرَاؤُهُ وَلَا بَيْعُهُ وَلَا شَيْءٌ ‏","","",""],[3162,3162,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏قَالَ ‏ ‏لَا يَجُوزُ طَلَاقٌ وَلَا وَصِيَّةٌ إِلَّا فِي عَقْلٍ إِلَّا النَّشْوَانَ ‏ ‏يَعْنِي السَّكْرَانَ ‏ ‏فَإِنَّهُ يَجُوزُ طَلَاقُهُ وَيُضْرَبُ ظَهْرُهُ ‏","","",""],[3163,3163,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَقَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏الْقَاسِمَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏وَمُعَاوِيَةَ بْنَ قُرَّةَ ‏ ‏عَنْ رَجُلٍ قَالَ فِي وَصِيَّتِهِ كُلُّ مَمْلُوكٍ لِي حُرٌّ وَلَهُ مَمْلُوكٌ ‏ ‏آبِقٌ ‏ ‏فَقَالَا ‏ ‏هُوَ حُرٌّ ‏ ‏و قَالَ ‏ ‏الْحَسَنُ ‏ ‏وَإِيَاسٌ ‏ ‏وَبَكْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏لَيْسَ بِحُرٍّ ‏","","",""],[3164,3164,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏أَوْصَى إِلَى ‏ ‏حَفْصَةَ أُمِّ الْمُؤْمِنِينَ ‏","","",""],[3165,3165,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ‏ ‏أَوْصَتْ لِنَسِيبٍ لَهَا يَهُودِيٍّ ‏","","",""],[3166,3166,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏قَالَ ‏ ‏أَوْصَى غُلَامٌ مِنْ الْحَيِّ يُقَالُ لَهُ ‏ ‏عَبَّاسُ بْنُ مَرْثَدٍ ‏ ‏ابْنُ سَبْعِ سِنِينَ ‏ ‏لِظِئْرٍ ‏ ‏لَهُ يَهُودِيَّةٍ مِنْ أَهْلِ ‏ ‏الْحِيرَةِ ‏ ‏بِأَرْبَعِينَ دِرْهَمًا ‏ ‏فَقَالَ ‏ ‏شُرَيْحٌ ‏ ‏إِذَا أَصَابَ الْغُلَامُ فِي وَصِيَّتِهِ جَازَتْ وَإِنَّمَا أَوْصَى لِذِي حَقٍّ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَنَا أَقُولُ بِهِ ‏","","",""],[3167,3167,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرَ ‏ ‏جَعَلَ دُورَهُ صَدَقَةً عَلَى بَنِيهِ لَا تُبَاعُ وَلَا تُوَرَّثُ وَأَنَّ ‏ ‏لِلْمَرْدُودَةِ ‏ ‏مِنْ بَنَاتِهِ أَنْ تَسْكُنَ غَيْرَ مُضِرَّةٍ وَلَا مُضَارٍّ بِهَا فَإِنْ هِيَ اسْتَغْنَتْ بِزَوْجٍ فَلَا حَقَّ لَهَا ‏","","",""],[3168,3168,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏الْوَلِيدُ ‏ ‏عَنْ ‏ ‏حَفْصٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏فِي الرَّجُلِ يُوصِي لِلرَّجُلِ بِدَنَانِيرَ فِي سَبِيلِ اللَّهِ فَيَمُوتُ الْمُوصَى لَهُ قَبْلَ أَنْ يَخْرُجَ بِهَا مِنْ أَهْلِهِ قَالَ ‏ ‏هِيَ إِلَى أَوْلِيَاءِ الْمُتَوَفَّى الْمُوصِي يُنْفِذُونَهَا فِي سَبِيلِ اللَّهِ ‏","","",""],[3169,3169,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏فِي الرَّجُلِ يُوصِي لِلرَّجُلِ بِالْوَصِيَّةِ فَيَمُوتُ الْمُوصَى لَهُ قَبْلَ الْمُوصِي قَالَ ‏ ‏هِيَ جَائِزَةٌ لِوَرَثَةِ الْمُوصَى لَهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ السَّبِيعِيِّ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏كَانَ يُجِيزُهَا ‏ ‏مِثْلَ قَوْلِ ‏ ‏الْحَسَنِ ‏","","",""],[3170,3170,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ هُوَ ابْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُوسَى هُوَ ابْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَ إِنَّ رَجُلًا أَوْصَى إِلَيَّ وَجَعَلَ نَاقَةً فِي سَبِيلِ اللَّهِ وَلَيْسَ هَذَا زَمَانًا يُخْرَجُ إِلَى الْغَزْوِ فَأَحْمِلُ عَلَيْهَا فِي الْحَجِّ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏الْحَجُّ وَالْعُمْرَةُ مِنْ سَبِيلِ اللَّهِ ‏","","",""],[3171,3171,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا أَوْصَى بِمَالِهِ فِي سَبِيلِ اللَّهِ فَسَأَلَ الْوَصِيُّ عَنْ ذَلِكَ ‏ ‏عُمَرَ ‏ ‏فَقَالَ ‏ ‏أَعْطِهِ عُمَّالَ اللَّهِ قَالَ وَمَنْ عُمَّالُ اللَّهِ قَالَ حَاجُّ ‏ ‏بَيْتِ اللَّهِ ‏","","",""],[3172,3172,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ زُرَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ الَّذِي لَيْسَ فِي جَوْفِهِ مِنْ الْقُرْآنِ شَيْءٌ كَالْبَيْتِ الْخَرِبِ ‏","","",""],[3173,3173,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ خَالِدِ بْنِ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سِنَانٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّ هَذَا الْقُرْآنَ مَأْدُبَةُ اللَّهِ فَخُذُوا مِنْهُ مَا اسْتَطَعْتُمْ فَإِنِّي لَا أَعْلَمُ شَيْئًا أَصْفَرَ مِنْ خَيْرٍ مِنْ بَيْتٍ لَيْسَ فِيهِ مِنْ كِتَابِ اللَّهِ شَيْءٌ وَإِنَّ الْقَلْبَ الَّذِي لَيْسَ فِيهِ مِنْ كِتَابِ اللَّهِ شَيْءٌ خَرِبٌ كَخَرَابِ الْبَيْتِ الَّذِي لَا سَاكِنَ لَهُ ‏","","",""],[3174,3174,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ قَبِيصَةُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏تَعَلَّمُوا هَذَا الْقُرْآنَ فَإِنَّكُمْ تُؤْجَرُونَ بِتِلَاوَتِهِ بِكُلِّ حَرْفٍ عَشْرَ حَسَنَاتٍ أَمَا إِنِّي لَا أَقُولُ بْ الم وَلَكِنْ بِأَلِفٍ ‏ ‏وَلَامٍ وَمِيمٍ بِكُلِّ حَرْفٍ عَشْرُ حَسَنَاتٍ ‏","","",""],[3175,3175,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هَانِئٍ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏حَفْصُ بْنُ عِنَانٍ الْحَنَفِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ الْبَيْتَ لَيَتَّسِعُ عَلَى أَهْلِهِ وَتَحْضُرُهُ الْمَلَائِكَةُ وَتَهْجُرُهُ الشَّيَاطِينُ وَيَكْثُرُ خَيْرُهُ أَنْ يُقْرَأَ فِيهِ الْقُرْآنُ وَإِنَّ الْبَيْتَ لَيَضِيقُ عَلَى أَهْلِهِ وَتَهْجُرُهُ الْمَلَائِكَةُ وَتَحْضُرُهُ الشَّيَاطِينُ وَيَقِلُّ خَيْرُهُ أَنْ لَا يُقْرَأَ فِيهِ الْقُرْآنُ ‏","","",""],[3176,3176,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مِشْرَحِ بْنِ هَاعَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ جُعِلَ الْقُرْآنُ فِي ‏ ‏إِهَابٍ ‏ ‏ثُمَّ أُلْقِيَ فِي النَّارِ مَا احْتَرَقَ ‏","","",""],[3177,3177,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ الرَّقِّيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي أُنَيْسَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏اقْرَءُوا الْقُرْآنَ فَإِنَّهُ نِعْمَ الشَّفِيعُ يَوْمَ الْقِيَامَةِ إِنَّهُ يَقُولُ يَوْمَ الْقِيَامَةِ يَا رَبِّ حَلِّهِ حِلْيَةَ الْكَرَامَةِ ‏ ‏فَيُحَلَّى حِلْيَةَ الْكَرَامَةِ يَا رَبِّ اكْسُهُ كِسْوَةَ الْكَرَامَةِ ‏ ‏فَيُكْسَى كِسْوَةَ الْكَرَامَةِ يَا رَبِّ أَلْبِسْهُ تَاجَ الْكَرَامَةِ يَا رَبِّ ارْضَ عَنْهُ فَلَيْسَ بَعْدَ رِضَاكَ شَيْءٌ ‏","","",""],[3178,3178,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُحَمَّدٍ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏يَجِيءُ الْقُرْآنُ يَشْفَعُ لِصَاحِبِهِ يَقُولُ يَا رَبِّ لِكُلِّ عَامِلٍ ‏ ‏عُمَالَةٌ ‏ ‏مِنْ عَمَلِهِ وَإِنِّي كُنْتُ أَمْنَعُهُ اللَّذَّةَ وَالنَّوْمَ فَأَكْرِمْهُ فَيُقَالُ ابْسُطْ يَمِينَكَ فَتُمْلَأُ مِنْ رِضْوَانِ اللَّهِ ثُمَّ يُقَالُ ابْسُطْ شِمَالَكَ فَتُمْلَأُ مِنْ رِضْوَانِ اللَّهِ ‏ ‏وَيُكْسَى كِسْوَةَ الْكَرَامَةِ ‏ ‏وَيُحَلَّى بِحِلْيَةِ الْكَرَامَةِ وَيُلْبَسُ تَاجَ الْكَرَامَةِ ‏","","",""],[3179,3179,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُحَمَّدٍ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏الْمُسَيَّبِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏الْقُرْآنُ يَشْفَعُ لِصَاحِبِهِ ‏ ‏فَيُكْسَى حُلَّةَ الْكَرَامَةِ ثُمَّ يَقُولُ رَبِّ زِدْهُ ‏ ‏فَيُكْسَى تَاجَ الْكَرَامَةِ قَالَ فَيَقُولُ رَبِّ زِدْهُ فَإِنَّهُ فَإِنَّهُ فَيَقُولُ رِضَائِي ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏قَالَ ‏ ‏وُهَيْبُ بْنُ الْوَرْدِ ‏ ‏اجْعَلْ قِرَاءَتَكَ الْقُرْآنَ عِلْمًا وَلَا تَجْعَلْهُ عَمَلًا ‏","","",""],[3180,3180,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ الْفَزَارِيُّ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُحِبُّ أَحَدُكُمْ إِذَا أَتَى أَهْلَهُ أَنْ يَجِدَ ثَلَاثَ ‏ ‏خَلِفَاتٍ ‏ ‏سِمَانٍ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ فَثَلَاثُ آيَاتٍ يَقْرَؤُهُنَّ أَحَدُكُمْ خَيْرٌ لَهُ مِنْهُنَّ ‏","","",""],[3181,3181,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ هُوَ الْهَجَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏إِنَّ هَذَا الْقُرْآنَ مَأْدُبَةُ اللَّهِ فَتَعَلَّمُوا مِنْ مَأْدُبَتِهِ مَا اسْتَطَعْتُمْ إِنَّ هَذَا الْقُرْآنَ حَبْلُ اللَّهِ وَالنُّورُ الْمُبِينُ وَالشِّفَاءُ النَّافِعُ عِصْمَةٌ لِمَنْ تَمَسَّكَ بِهِ وَنَجَاةٌ لِمَنْ اتَّبَعَهُ لَا يَزِيغُ فَيَسْتَعْتِبُ وَلَا يَعْوَجُّ فَيُقَوَّمُ وَلَا تَنْقَضِي عَجَائِبُهُ وَلَا ‏ ‏يَخْلَقُ ‏ ‏عَنْ كَثْرَةِ الرَّدِّ فَاتْلُوهُ فَإِنَّ اللَّهَ يَأْجُرُكُمْ عَلَى تِلَاوَتِهِ بِكُلِّ حَرْفٍ عَشْرَ حَسَنَاتٍ أَمَا إِنِّي لَا أَقُولُ الم وَلَكِنْ بِأَلِفٍ ‏ ‏وَلَامٍ وَمِيمٍ ‏","","",""],[3182,3182,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْقَمَ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا خَطِيبًا فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّمَا أَنَا بَشَرٌ يُوشِكُ أَنْ يَأْتِيَنِي رَسُولُ رَبِّي فَأُجِيبَهُ وَإِنِّي تَارِكٌ فِيكُمْ الثَّقَلَيْنِ أَوَّلُهُمَا كِتَابُ اللَّهِ فِيهِ الْهُدَى وَالنُّورُ فَتَمَسَّكُوا بِكِتَابِ اللَّهِ وَخُذُوا بِهِ فَحَثَّ عَلَيْهِ وَرَغَّبَ فِيهِ ثُمَّ قَالَ وَأَهْلَ بَيْتِي أُذَكِّرُكُمْ اللَّهَ فِي أَهْلِ بَيْتِي ثَلَاثَ مَرَّاتٍ ‏","","",""],[3183,3183,"","","‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّ هَذَا الصِّرَاطَ مُحْتَضَرٌ تَحْضُرُهُ الشَّيَاطِينُ يُنَادُونَ يَا عَبْدَ اللَّهِ هَذَا الطَّرِيقُ فَاعْتَصِمُوا بِحَبْلِ اللَّهِ فَإِنَّ حَبْلَ اللَّهِ الْقُرْآنُ ‏","","",""],[3184,3184,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏قَالَ ‏ ‏إِنَّ قَارِئَ الْقُرْآنِ وَالْمُتَعَلِّمَ تُصَلِّي عَلَيْهِمْ الْمَلَائِكَةُ حَتَّى يَخْتِمُوا السُّورَةَ فَإِذَا أَقْرَأَ أَحَدُكُمْ السُّورَةَ فَلْيُؤَخِّرْ مِنْهَا آيَتَيْنِ حَتَّى يَخْتِمَهَا مِنْ آخِرِ النَّهَارِ كَيْ مَا تُصَلِّي الْمَلَائِكَةُ عَلَى الْقَارِئِ وَالْمُقْرِئِ مِنْ أَوَّلِ النَّهَارِ إِلَى آخِرِهِ ‏","","",""],[3185,3185,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ مُسْلِمٍ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏اقْرَءُوا الْقُرْآنَ وَلَا يَغُرَّنَّكُمْ هَذِهِ الْمَصَاحِفُ الْمُعَلَّقَةُ فَإِنَّ اللَّهَ لَنْ يُعَذِّبَ قَلْبًا وَعَى الْقُرْآنَ ‏","","",""],[3186,3186,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏سُلَيْمِ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏قَالَ ‏ ‏اقْرَءُوا الْقُرْآنَ وَلَا يَغُرَّنَّكُمْ هَذِهِ الْمَصَاحِفُ الْمُعَلَّقَةُ فَإِنَّ اللَّهَ لَا يُعَذِّبُ قَلْبًا وَعَى الْقُرْآنَ ‏","","",""],[3187,3187,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏مَعْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنْ مُؤَدِّبٍ إِلَّا وَهُوَ يُحِبُّ أَنْ يُؤْتَى أَدَبُهُ وَإِنَّ أَدَبَ اللَّهِ الْقُرْآنُ ‏","","",""],[3188,3188,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏قَالَ كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذَا الْقُرْآنَ مَأْدُبَةُ اللَّهِ فَمَنْ دَخَلَ فِيهِ فَهُوَ آمِنٌ ‏","","",""],[3189,3189,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَنْ أَحَبَّ الْقُرْآنَ فَلْيُبْشِرْ ‏","","",""],[3190,3190,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَنْ أَحَبَّ الْقُرْآنَ فَلْيُبْشِرْ ‏","","",""],[3191,3191,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النُّجُودِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏أَنَّ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏كَانَ يَقُولُ ‏ ‏يَجِيءُ الْقُرْآنُ يَوْمَ الْقِيَامَةِ فَيَشْفَعُ لِصَاحِبِهِ فَيَكُونُ لَهُ قَائِدًا إِلَى الْجَنَّةِ وَيَشْهَدُ عَلَيْهِ وَيَكُونُ لَهُ سَائِقًا إِلَى النَّارِ ‏","","",""],[3192,3192,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ أَبِي جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏بُدَيْلٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِلَّهِ أَهْلِينَ مِنْ النَّاسِ قِيلَ يَا رَسُولَ اللَّهِ مَنْ هُمْ قَالَ أَهْلُ الْقُرْآنِ ‏","","",""],[3193,3193,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏مُغِيثٍ ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏قَالَ ‏ ‏عَلَيْكُمْ بِالْقُرْآنِ فَإِنَّهُ فَهْمُ الْعَقْلِ وَنُورُ الْحِكْمَةِ وَيَنَابِيعُ الْعِلْمِ وَأَحْدَثُ الْكُتُبِ بِالرَّحْمَنِ عَهْدًا وَقَالَ فِي التَّوْرَاةِ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي مُنَزِّلٌ عَلَيْكَ تَوْرَاةً حَدِيثَةً تَفْتَحُ فِيهَا أَعْيُنًا عُمْيًا وَآذَانًا صُمًّا وَقُلُوبًا ‏ ‏غُلْفًا ‏","","",""],[3194,3194,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ مِخْرَاقٍ ‏ ‏عَنْ ‏ ‏أَبِي إِيَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي كِنَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ هَذَا الْقُرْآنَ كَائِنٌ لَكُمْ أَجْرًا وَكَائِنٌ لَكُمْ ذِكْرًا وَكَائِنٌ بِكُمْ نُورًا وَكَائِنٌ عَلَيْكُمْ وِزْرًا اتَّبِعُوا الْقُرْآنَ وَلَا يَتَّبِعْكُمْ الْقُرْآنُ فَإِنَّهُ مَنْ يَتَّبِعْ الْقُرْآنَ يَهْبِطْ بِهِ فِي رِيَاضِ الْجَنَّةِ وَمَنْ اتَّبَعَهُ الْقُرْآنُ يَزُخُّ فِي قَفَاهُ فَيَقْذِفُهُ فِي جَهَنَّمَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَزُخُّ يَدْفَعُ ‏","","",""],[3195,3195,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ أَيُّوبَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمِّي ‏ ‏إِيَاسَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏أَخَذَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏بِيَدِي ثُمَّ قَالَ ‏ ‏إِنَّكَ إِنْ بَقِيتَ سَيَقْرَأُ الْقُرْآنَ ثَلَاثَةُ أَصْنَافٍ فَصِنْفٌ لِلَّهِ وَصِنْفٌ لِلْجِدَالِ وَصِنْفٌ لِلدُّنْيَا وَمَنْ طَلَبَ بِهِ أَدْرَكَ ‏","","",""],[3196,3196,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا قَالَ ‏ ‏لِأَبِي الدَّرْدَاءِ ‏ ‏إِنَّ إِخْوَانَكَ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏مِنْ أَهْلِ الذِّكْرِ يُقْرِئُونَكَ السَّلَامَ فَقَالَ ‏ ‏وَعَلَيْهِمْ السَّلَامُ وَمُرْهُمْ فَلْيُعْطُوا الْقُرْآنَ ‏ ‏بِخَزَائِمِهِمْ ‏ ‏فَإِنَّهُ يَحْمِلُهُمْ عَلَى ‏ ‏الْقَصْدِ ‏ ‏وَالسُّهُولَةِ وَيُجَنِّبُهُمْ الْجَوْرَ وَالْحُزُونَةَ ‏","","",""],[3197,3197,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الرِّفَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ الزَّيَّاتِ ‏ ‏عَنْ ‏ ‏أَبِي الْمُخْتَارِ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ أَخِي الْحَارِثِ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْمَسْجِدَ فَإِذَا أُنَاسٌ يَخُوضُونَ فِي أَحَادِيثَ فَدَخَلْتُ عَلَى ‏ ‏عَلِيٍّ ‏ ‏فَقُلْتُ أَلَا ‏ ‏تَرَى أَنَّ أُنَاسًا يَخُوضُونَ فِي الْأَحَادِيثِ فِي الْمَسْجِدِ فَقَالَ قَدْ فَعَلُوهَا قُلْتُ نَعَمْ قَالَ أَمَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَتَكُونُ فِتَنٌ قُلْتُ وَمَا الْمَخْرَجُ مِنْهَا قَالَ كِتَابُ اللَّهِ كِتَابُ اللَّهِ فِيهِ نَبَأُ مَا قَبْلَكُمْ وَخَبَرُ مَا بَعْدَكُمْ وَحُكْمُ مَا بَيْنَكُمْ هُوَ ‏ ‏الْفَصْلُ ‏ ‏لَيْسَ بِالْهَزْلِ هُوَ الَّذِي مَنْ تَرَكَهُ مِنْ جَبَّارٍ قَصَمَهُ اللَّهُ وَمَنْ ابْتَغَى الْهُدَى فِي غَيْرِهِ أَضَلَّهُ اللَّهُ فَهُوَ حَبْلُ اللَّهِ الْمَتِينُ وَهُوَ الذِّكْرُ الْحَكِيمُ وَهُوَ الصِّرَاطُ الْمُسْتَقِيمُ وَهُوَ الَّذِي لَا تَزِيغُ بِهِ الْأَهْوَاءُ وَلَا تَلْتَبِسُ بِهِ الْأَلْسِنَةُ وَلَا يَشْبَعُ مِنْهُ الْعُلَمَاءُ وَلَا ‏ ‏يَخْلَقُ ‏ ‏عَنْ كَثْرَةِ الرَّدِّ وَلَا تَنْقَضِي عَجَائِبُهُ وَهُوَ الَّذِي لَمْ يَنْتَهِ الْجِنُّ إِذْ سَمِعَتْهُ أَنْ قَالُوا ‏ { ‏إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا ‏} ‏هُوَ الَّذِي مَنْ قَالَ بِهِ صَدَقَ وَمَنْ حَكَمَ بِهِ عَدَلَ وَمَنْ عَمِلَ بِهِ أُجِرَ وَمَنْ دَعَا إِلَيْهِ هُدِيَ إِلَى صِرَاطٍ مُسْتَقِيمٍ خُذْهَا إِلَيْكَ يَا أَعْوَرُ ‏","","",""],[3198,3198,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ إِنَّ أُمَّتَكَ سَتُفْتَتَنُ مِنْ بَعْدِكَ قَالَ فَسَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ سُئِلَ ‏ ‏مَا الْمَخْرَجُ مِنْهَا قَالَ ‏ ‏الْكِتَابُ الْعَزِيزُ الَّذِي ‏ { ‏لَا يَأْتِيهِ الْبَاطِلُ مِنْ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِ تَنْزِيلٌ مِنْ حَكِيمٍ حَمِيدٍ ‏} ‏مَنْ ابْتَغَى الْهُدَى فِي غَيْرِهِ أَضَلَّهُ اللَّهُ وَمَنْ وَلِيَ هَذَا الْأَمْرَ مِنْ جَبَّارٍ فَحَكَمَ بِغَيْرِهِ قَصَمَهُ اللَّهُ هُوَ الذِّكْرُ الْحَكِيمُ وَالنُّورُ الْمُبِينُ وَالصِّرَاطُ الْمُسْتَقِيمُ فِيهِ خَبَرُ مَنْ قَبْلَكُمْ وَنَبَأُ مَا بَعْدَكُمْ وَحُكْمُ مَا بَيْنَكُمْ وَهُوَ ‏ ‏الْفَصْلُ ‏ ‏لَيْسَ بِالْهَزْلِ وَهُوَ الَّذِي سَمِعَتْهُ الْجِنُّ فَلَمْ ‏ ‏تَتَنَاهَى أَنْ قَالُوا ‏ { ‏إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا يَهْدِي إِلَى الرُّشْدِ ‏} ‏وَلَا ‏ ‏يَخْلَقُ ‏ ‏عَنْ كَثْرَةِ الرَّدِّ وَلَا تَنْقَضِي عِبَرُهُ وَلَا ‏ ‏تَفْنَى عَجَائِبُهُ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏لِلْحَارِثِ ‏ ‏خُذْهَا إِلَيْكَ يَا أَعْوَرُ ‏","","",""],[3199,3199,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ { ‏وَمَنْ يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْرًا كَثِيرًا ‏} ‏قَالَ ‏ ‏الْفَهْمَ بِالْقُرْآنِ ‏","","",""],[3200,3200,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏وَرْقَاءَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ { ‏يُؤْتِي الْحِكْمَةَ مَنْ يَشَاءُ ‏} ‏قَالَ ‏ ‏الْكِتَابَ يُؤْتِي إِصَابَتَهُ مَنْ يَشَاءُ ‏","","",""]];
